SELECT t.grid_id AS code, SUM(t.num)::numeric / NULLIF(SUM(t.total), 0) AS result FROM ( SELECT p.grid_id, (p.gender_female + p.gender_male) AS total, tp.there_room AS num FROM tb_grid_pop_attr1 p JOIN tb_grid_personalized_portrait tp ON p.grid_id = tp.grid_id AND p.population_type = tp.population_type WHERE p.grid_id IN
#{item}
AND p.date = #{date} AND p.population_type = #{populationType} ) t GROUP BY t.grid_id

SELECT t.grid_id AS code, SUM(t.num)::numeric / NULLIF(SUM(t.total), 0) AS result FROM ( SELECT p.grid_id, CASE WHEN tp.white_collar_general_staff_proportion = 0 THEN 0 ELSE (tp.white_collar_general_staff / tp.white_collar_general_staff_proportion) END AS total, tp.white_collar_general_staff AS num FROM tb_grid_pop_attr1 p JOIN tb_grid_personalized_portrait tp ON p.grid_id = tp.grid_id AND p.population_type = tp.population_type WHERE p.grid_id IN
#{item}
AND p.date = #{date} AND p.population_type = #{populationType} ) t GROUP BY t.grid_id

