SELECT p.grid_id AS code, (hf.num / 14400.0) / #{totalArea} AS result FROM tb_grid_pop_attr1 p JOIN tb_grid_hour_flow hf ON p.grid_id = hf.grid_id WHERE p.grid_id IN
#{item}
AND p.date = #{date}

SELECT p.grid_id AS code, (pn.num / 14400.0) / #{avgPerGrid} AS result FROM tb_grid_pop_attr1 p JOIN tb_grid_permanent_num pn ON p.grid_id = pn.grid_id AND pn.population_type = 'HOME' WHERE p.grid_id IN
#{item}
AND p.date = #{date}

SELECT p.grid_id AS code, (pn.num / 14400.0) / #{avgPerGrid} AS result FROM tb_grid_pop_attr1 p JOIN tb_grid_permanent_num pn ON p.grid_id = pn.grid_id AND pn.population_type = 'WORK' WHERE p.grid_id IN
#{item}
AND p.date = #{date}

SELECT p.grid_id AS code, (work_flow.num / NULLIF(holiday_flow.num, 0)) AS result FROM tb_grid_pop_attr1 p JOIN tb_grid_hour_flow work_flow ON p.grid_id = work_flow.grid_id AND work_flow.type = 'WROK_HOUR_FLOW' JOIN tb_grid_hour_flow holiday_flow ON p.grid_id = holiday_flow.grid_id AND holiday_flow.type = 'HOLIDAY_HOUR_FLOW' WHERE p.grid_id IN
#{item}
AND p.date = #{date}
